SET statement_timeout TO 0; SET lock_timeout TO 0; SET idle_in_transaction_session_timeout TO 0; SET transaction_timeout TO 0; SET client_encoding TO "UTF8"; SET standard_conforming_strings TO ON; SELECT pg_catalog.set_config('search_path', '', false); SET check_function_bodies TO FALSE; SET xmloption TO content; SET client_min_messages TO warning; SET row_security TO OFF; CREATE SCHEMA sales; ALTER SCHEMA sales OWNER TO postgres; CREATE COLLATION sales.code_order (provider = libc, locale = 'C'); ALTER COLLATION sales.code_order OWNER TO postgres; CREATE TYPE sales.address AS (street text, postcode text); ALTER TYPE sales.address OWNER TO postgres; CREATE DOMAIN sales.money_amount AS numeric(38, 9) CONSTRAINT money_amount_check CHECK (value >= 0::numeric); ALTER DOMAIN sales.money_amount OWNER TO postgres; CREATE TYPE sales.order_state AS ENUM ('new', 'paid', 'cancelled'); ALTER TYPE sales.order_state OWNER TO postgres; CREATE TYPE sales.price_span AS RANGE (subtype = numeric, multirange_type_name = sales.price_spans); ALTER TYPE sales.price_span OWNER TO postgres; CREATE DOMAIN sales.text AS int CONSTRAINT text_check CHECK (value >= 0); ALTER DOMAIN sales.text OWNER TO postgres; CREATE FUNCTION public.echo_text(value text) RETURNS text LANGUAGE sql IMMUTABLE AS $$ SELECT value $$; ALTER FUNCTION public.echo_text(value text) OWNER TO postgres; CREATE FUNCTION sales.normalize_inventory() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 NEW.normalized := upper(NEW.code);
 RETURN NEW;
END
$$; ALTER FUNCTION sales.normalize_inventory() OWNER TO postgres; SET default_tablespace TO ''; CREATE TABLE public.events (at timestamp with time zone NOT NULL, payload jsonb) PARTITION BY RANGE(at); ALTER TABLE public.events OWNER TO postgres; SET default_table_access_method TO heap; CREATE TABLE public.events_2026 (at timestamp with time zone NOT NULL, payload jsonb); ALTER TABLE public.events_2026 OWNER TO postgres; CREATE VIEW public.recent_events AS SELECT at, payload FROM public.events WHERE at > (now() - '1 day'::interval); ALTER VIEW public.recent_events OWNER TO postgres; CREATE TABLE sales.inventory (code text NOT NULL COLLATE sales.code_order, address sales.address, prices sales.price_span, history sales.price_spans, normalized text); ALTER TABLE sales.inventory OWNER TO postgres; CREATE MATERIALIZED VIEW sales.inventory_totals AS SELECT count(*) AS total FROM sales.inventory WITH NO DATA; ALTER MATERIALIZED VIEW sales.inventory_totals OWNER TO postgres; CREATE TABLE sales.order_lines (order_id bigint NOT NULL, line_no int NOT NULL, quantity int, CONSTRAINT order_lines_quantity_check CHECK (quantity > 0)); ALTER TABLE sales.order_lines OWNER TO postgres; CREATE TABLE sales.orders (id bigint NOT NULL, external_id uuid NOT NULL, state sales.order_state DEFAULT ('new'::sales.order_state) NOT NULL, total sales.money_amount DEFAULT 9007199254740993.123456789, details jsonb, tags text[] DEFAULT (ARRAY[]::text[]), created_at timestamp with time zone DEFAULT now(), subtotal numeric GENERATED ALWAYS AS (total::numeric / 1.2) STORED, CONSTRAINT positive_total CHECK (total::numeric >= 0::numeric)); ALTER TABLE sales.orders OWNER TO postgres; COMMENT ON COLUMN sales.orders.total IS 'Exact amount — café'; ALTER TABLE sales.orders ALTER id ADD GENERATED ALWAYS AS IDENTITY (SEQUENCE NAME sales.orders_id_seq START 1 INCREMENT 1 NO MINVALUE NO MAXVALUE CACHE 1 ); CREATE TABLE sales.row_encodings (id int NOT NULL, active boolean NOT NULL, optional_flag boolean, nullable_json jsonb, required_json jsonb NOT NULL, label text, small_value smallint NOT NULL); ALTER TABLE sales.row_encodings OWNER TO postgres; CREATE TABLE sales.scalar_types (flag boolean, small smallint, ordinary int, large bigint, exact numeric(20, 4), single real, wide double precision, words text, bounded varchar(20), padded char(4), data bytea, day date, clock time(3), zoned_clock time with time zone, local_stamp timestamp(6), instant timestamp with time zone, items int[], domain_value sales.text, document jsonb, identifier uuid); ALTER TABLE sales.scalar_types OWNER TO postgres; COMMENT ON COLUMN sales.scalar_types.exact IS 'Exact amount with native precision and scale'; CREATE SEQUENCE sales.ticket_numbers START 9007199254740993 INCREMENT 3 NO MINVALUE NO MAXVALUE CACHE 2; ALTER SEQUENCE sales.ticket_numbers OWNER TO postgres; ALTER TABLE ONLY public.events ATTACH PARTITION public.events_2026 FOR VALUES FROM ('2026-01-01 00:00:00+00') TO ('2027-01-01 00:00:00+00'); ALTER TABLE ONLY sales.inventory ADD CONSTRAINT inventory_pkey PRIMARY KEY (code); ALTER TABLE ONLY sales.order_lines ADD CONSTRAINT order_lines_pkey PRIMARY KEY (order_id, line_no); ALTER TABLE ONLY sales.orders ADD CONSTRAINT orders_external_id_key UNIQUE (external_id); ALTER TABLE ONLY sales.orders ADD CONSTRAINT orders_pkey PRIMARY KEY (id); ALTER TABLE ONLY sales.row_encodings ADD CONSTRAINT row_encodings_pkey PRIMARY KEY (id); CREATE UNIQUE INDEX inventory_totals_unique ON sales.inventory_totals USING btree (total); CREATE INDEX paid_orders ON sales.orders USING btree (created_at DESC) WHERE state = 'paid'::sales.order_state; CREATE TRIGGER normalize_inventory BEFORE INSERT OR UPDATE OF code ON sales.inventory FOR EACH ROW EXECUTE FUNCTION sales.normalize_inventory(); COMMENT ON TRIGGER normalize_inventory ON sales.inventory IS 'Normalize display code — retain trigger intent'; ALTER TABLE ONLY sales.order_lines ADD CONSTRAINT order_lines_order_id_fkey FOREIGN KEY (order_id) REFERENCES sales.orders (id) ON DELETE CASCADE; ALTER TABLE public.events ENABLE ROW LEVEL SECURITY; CREATE POLICY visible_events ON public.events FOR SELECT TO public USING ((payload ->> 'tenant'::text) = current_user) ; GRANT select ON public.events TO public
